        display: .system(size: 36, weight: .bold),
        control: 56
    )

    static let large = TypeScale(
        name: "large",
        answer: .system(size: 34, weight: .semibold),
        answerTracking: -0.8,
        time: .system(size: 36, weight: .semibold),
