/// Bottom contextual sheet with 16px side margins on mobile, card radius 24,
/// dynamic Liquid Glass on iOS 26 with fallback to .ultraThinMaterial.
private struct SheetScaffold<Content: View, Actions: View>: View {
    let title: String
    @ViewBuilder var content: Content
    @ViewBuilder var actions: Actions

    @Environment(\.typeScale) private var type

    var body: some View {
        VStack(alignment: .leading, spacing: 20) {
            Text(title)
                .font(type.section)
                .tracking(-0.7)
                .foregroundStyle(Theme.textPrimary)
                .padding(.top, 24)
            ScrollView {
                content
            }
            .scrollBounceBehavior(.basedOnSize)
            actions
        }
        .padding(.horizontal, Theme.Size.cardGutterMobile)
        .padding(.bottom, 16)
        .presentationBackground {
            if #available(iOS 26.0, *) {
                Color.clear
                    .glassEffect()
            } else {
                ZStack {
                    Rectangle().fill(.ultraThinMaterial)
                    Theme.surface.opacity(0.92)
                }
            }
        }
        .presentationCornerRadius(Theme.Radius.card)
        .presentationDragIndicator(.visible)
    }
}

private struct ToggleRow: View {
    let title: String
    let detail: String
    @Binding var isOn: Bool

    @Environment(\.typeScale) private var type

    var body: some View {
        Toggle(isOn: $isOn) {
            VStack(alignment: .leading, spacing: 4) {
                Text(title)
                    .font(type.bodyStrong)
                    .foregroundStyle(Theme.textPrimary)
                Text(detail)
                    .font(type.meta)
                    .foregroundStyle(Theme.textMuted)
            }
        }
        .tint(Theme.textPrimary)
        .padding(16)
        .background(RoundedRectangle(cornerRadius: Theme.Radius.control, style: .continuous).fill(Theme.raised))
        .overlay(RoundedRectangle(cornerRadius: Theme.Radius.control, style: .continuous).strokeBorder(Theme.border, lineWidth: 1))
    }
}

private struct LabeledField<Field: View>: View {
    let title: String
    @ViewBuilder var field: Field

    @Environment(\.typeScale) private var type

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(title)
                .eyebrow(type, color: Theme.textMuted)
            field
                .font(type.body)
                .foregroundStyle(Theme.textPrimary)
                .padding(.horizontal, 16)
                .frame(minHeight: max(Theme.Size.inputHeight, type.control))
                .background(RoundedRectangle(cornerRadius: Theme.Radius.control, style: .continuous).fill(Theme.surface))
                .overlay(RoundedRectangle(cornerRadius: Theme.Radius.control, style: .continuous).strokeBorder(Theme.border, lineWidth: 1))
        }
    }
}

