        let shape = RoundedRectangle(cornerRadius: Theme.Radius.control, style: .continuous)
        configuration.label
            .font(type.label)
            .foregroundStyle(selected ? Theme.surface : Theme.textPrimary)
            .frame(maxWidth: .infinity, minHeight: Theme.Size.touchMin)
            .background(shape.fill(selected ? Theme.textPrimary : Theme.raised))
            .overlay(shape.strokeBorder(selected ? Theme.textPrimary : Theme.border, lineWidth: 1))
            .opacity(configuration.isPressed ? 0.8 : 1)
    }
}

