struct Confirmation: Equatable {
    let title: String
    let details: [(String, String)]

    static func == (lhs: Confirmation, rhs: Confirmation) -> Bool {
        lhs.title == rhs.title && lhs.details.map { "\($0.0):\($0.1)" } == rhs.details.map { "\($0.0):\($0.1)" }
    }
}

private(set) var confirmation: Confirmation?
private(set) var doneMessage: String?
private(set) var errorMessage: String?
private(set) var connection: Connection = .fixtures

func showConfirmation(title: String, details: [(String, String)]) {
    self.confirmation = Confirmation(title: title, details: details)
    self.doneMessage = nil
    self.errorMessage = nil
    self.reply = nil
}

func confirmAction() {
    if let conf = confirmation {
        self.confirmation = nil
        self.doneMessage = "Changes saved: \(conf.title)"
        self.label = "Added to your calendar"
    }
}

func cancelAction() {
    self.confirmation = nil
    self.label = "Ready"
}

func showDone(message: String) {
    self.doneMessage = message
    self.confirmation = nil
    self.errorMessage = nil
}

