private struct Welcome: View {
    var listening = false
    var handsFree = false
    @Environment(\.typeScale) private var type

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            Text(listening ? "I'm listening…" : "What do you need?")
                .font(type.display)
                .tracking(-0.5)
                .foregroundStyle(Theme.textPrimary)
